WITH docs AS (SELECT value AS doc FROM jsonb_array_elements($authored$[{"case_key":"bank-legal-2026-101","title":"Один бюллетень за соседа","category":"Правовая практика","situation":"Член комиссии выдаёт избирателю дополнительный бюллетень за соседа после предъявления фотографии его паспорта. Сосед на участок не пришёл.\n\nНа участке осталось достаточно бюллетеней, а очередь небольшая. Избиратель говорит, что сосед болен, и показывает фотографию его паспорта в телефоне. Доверенности, личного присутствия соседа и заявления о предусмотренной законом форме голосования нет. Участнику переданы список избирателей и журнал выдачи; решение нужно принять до выдачи второго бюллетеня.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["цик","избирательной комиссии"],"decision_options":["Выдать бюллетень только надлежащему избирателю по установленной процедуре; голосование за отсутствующего соседа не допускается, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Выдать бюллетень за соседа по фотографии его паспорта, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Выдать бюллетень только надлежащему избирателю по установленной процедуре; голосование за отсутствующего соседа не допускается. Основание: Федеральный закон № 67-ФЗ, личное голосование и выдача бюллетеней. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: цик, избирательной комиссии. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Выдать бюллетень только надлежащему избирателю по установленной процедуре; голосование за отсутствующего соседа не допускается. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["цик","избирательной комиссии"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 67-ФЗ, личное голосование и выдача бюллетеней. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["цик","избирательной комиссии"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 67-ФЗ, личное голосование и выдача бюллетеней. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["цик","избирательной комиссии"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 67-ФЗ, личное голосование и выдача бюллетеней. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["цик","избирательной комиссии"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 67-ФЗ, личное голосование и выдача бюллетеней. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Выдать бюллетень за соседа по фотографии его паспорта. Надлежащий шаг: Выдать бюллетень только надлежащему избирателю по установленной процедуре; голосование за отсутствующего соседа не допускается. Основание: Федеральный закон № 67-ФЗ, личное голосование и выдача бюллетеней. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: цик, избирательной комиссии. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Выдать бюллетень за соседа по фотографии его паспорта. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["цик","избирательной комиссии"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 67-ФЗ, личное голосование и выдача бюллетеней. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-151","title":"Один бюллетень за соседа","case_key":"bank-legal-2026-101","format":"animated-svg","version":4,"alt":"Один бюллетень за соседа: участники изучают выбор и протокол и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Один бюллетень за соседа»: Член комиссии выдаёт избирателю дополнительный бюллетень за соседа после предъявления фотографии его паспорта. Сосед на участок не пришёл."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 67-ФЗ, личное голосование и выдача бюллетеней.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-102","title":"Победитель с конфликтом интересов","category":"Правовая практика","situation":"Руководитель закупочной комиссии узнал, что участником конкурса стала компания его супруги. Он решил просто не выступать на заседании, сохранив голос.\n\nЗаявки ещё оцениваются, итоговый протокол не подписан. Компания супруги руководителя предлагает цену на 2% ниже конкурента, но по качеству оценки расходятся. Руководитель сообщил секретарю о родстве и попросил только не давать ему слово. Участник должен определить порядок действий комиссии до выставления окончательных баллов.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Уведомить о конфликте и обеспечить предусмотренное отстранение от участия в принятии решения, а не только от выступления, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Сохранить голос в комиссии по заявке компании супруги, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Уведомить о конфликте и обеспечить предусмотренное отстранение от участия в принятии решения, а не только от выступления. Основание: Федеральные законы № 273-ФЗ и № 44-ФЗ, конфликт интересов. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Стратегический критерий: Защита репутации закупочной комиссии через отвод при конфликте. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Уведомить о конфликте и обеспечить предусмотренное отстранение от участия в принятии решения, а не только от выступления. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":"Защита репутации закупочной комиссии через отвод при конфликте.","legal_basis":"Федеральные законы № 273-ФЗ и № 44-ФЗ, конфликт интересов. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита репутации закупочной комиссии через отвод при конфликте.","legal_basis":"Федеральные законы № 273-ФЗ и № 44-ФЗ, конфликт интересов. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита репутации закупочной комиссии через отвод при конфликте.","legal_basis":"Федеральные законы № 273-ФЗ и № 44-ФЗ, конфликт интересов. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":"Защита репутации закупочной комиссии через отвод при конфликте.","legal_basis":"Федеральные законы № 273-ФЗ и № 44-ФЗ, конфликт интересов. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Сохранить голос в комиссии по заявке компании супруги. Надлежащий шаг: Уведомить о конфликте и обеспечить предусмотренное отстранение от участия в принятии решения, а не только от выступления. Основание: Федеральные законы № 273-ФЗ и № 44-ФЗ, конфликт интересов. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Сохранить голос в комиссии по заявке компании супруги. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральные законы № 273-ФЗ и № 44-ФЗ, конфликт интересов. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-152","title":"Победитель с конфликтом интересов","case_key":"bank-legal-2026-102","format":"animated-svg","version":4,"alt":"Победитель с конфликтом интересов: участники изучают целевой объект и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Победитель с конфликтом интересов»: Руководитель закупочной комиссии узнал, что участником конкурса стала компания его супруги. Он решил просто не выступать на заседании, сохранив голос."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральные законы № 273-ФЗ и № 44-ФЗ, конфликт интересов.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-103","title":"Дробление единой закупки","category":"Правовая практика","situation":"Учреждение разбило одну заранее известную потребность на множество малых договоров с тем же поставщиком, чтобы не проводить конкурентную процедуру.\n\nГодовой план учреждения содержит единую потребность в 120 компьютерах для одного корпуса. Проект предлагает двадцать договоров по шесть устройств с одинаковыми характеристиками и сроком доставки. Все договоры подготовлены для одного поставщика в одну неделю. Участнику доступны план и проекты договоров; необходимо выбрать способ оформления закупки до подписания.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Оценить совокупную потребность и применить надлежащий способ закупки; искусственное дробление не обосновывает исключение, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Разбить единую закупку на малые договоры ради обхода конкурса, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Оценить совокупную потребность и применить надлежащий способ закупки; искусственное дробление не обосновывает исключение. Основание: Федеральный закон № 44-ФЗ, принципы закупок и основания закупки у единственного поставщика. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Оценить совокупную потребность и применить надлежащий способ закупки; искусственное дробление не обосновывает исключение. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, принципы закупок и основания закупки у единственного поставщика. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, принципы закупок и основания закупки у единственного поставщика. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, принципы закупок и основания закупки у единственного поставщика. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, принципы закупок и основания закупки у единственного поставщика. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Разбить единую закупку на малые договоры ради обхода конкурса. Надлежащий шаг: Оценить совокупную потребность и применить надлежащий способ закупки; искусственное дробление не обосновывает исключение. Основание: Федеральный закон № 44-ФЗ, принципы закупок и основания закупки у единственного поставщика. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Разбить единую закупку на малые договоры ради обхода конкурса. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 44-ФЗ, принципы закупок и основания закупки у единственного поставщика. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-153","title":"Дробление единой закупки","case_key":"bank-legal-2026-103","format":"animated-svg","version":4,"alt":"Дробление единой закупки: участники изучают целевой объект и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Дробление единой закупки»: Учреждение разбило одну заранее известную потребность на множество малых договоров с тем же поставщиком, чтобы не проводить конкурентную процедуру."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 44-ФЗ, принципы закупок и основания закупки у единственного поставщика.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-104","title":"Техническое задание под марку","category":"Правовая практика","situation":"Заказчик описал характеристики оборудования так, что им соответствует только один бренд. Потребность в именно этой марке не обоснована, эквиваленты запрещены.\n\nВ техническом задании повторены уникальные размеры и закрытый интерфейс одной модели оборудования. Специалист объясняет выбор привычкой сотрудников, но не представил расчёт совместимости или иной объективной необходимости. Два поставщика запросили допуск эквивалентов. Участник рассматривает проект извещения до публикации на площадке.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Составить описание объекта закупки по допустимым объективным требованиям; товарный знак использовать только при законных условиях, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Запретить эквиваленты бренда без предусмотренного основания, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Составить описание объекта закупки по допустимым объективным требованиям; товарный знак использовать только при законных условиях. Основание: Федеральный закон № 44-ФЗ, статья 33. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Составить описание объекта закупки по допустимым объективным требованиям; товарный знак использовать только при законных условиях. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, статья 33. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, статья 33. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, статья 33. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, статья 33. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Запретить эквиваленты бренда без предусмотренного основания. Надлежащий шаг: Составить описание объекта закупки по допустимым объективным требованиям; товарный знак использовать только при законных условиях. Основание: Федеральный закон № 44-ФЗ, статья 33. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Запретить эквиваленты бренда без предусмотренного основания. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 44-ФЗ, статья 33. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-154","title":"Техническое задание под марку","case_key":"bank-legal-2026-104","format":"animated-svg","version":4,"alt":"Техническое задание под марку: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Техническое задание под марку»: Заказчик описал характеристики оборудования так, что им соответствует только один бренд. Потребность в именно этой марке не обоснована, эквиваленты запрещены."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 44-ФЗ, статья 33.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-105","title":"Приёмка того, чего нет","category":"Правовая практика","situation":"Поставщик просит подписать акт до поставки, чтобы закрыть год. На складе нет товара; он обещает доставить его после праздников.\n\nКонтракт предусматривает поставку 30 комплектов оборудования, а оплачивать можно после подтверждённой приёмки. Поставщик прислал подписанный со своей стороны акт и обещает привезти товар через две недели. Кладовщик письменно подтвердил отсутствие комплектов на складе. Участник должен решить, какой документ и какое действие допустимы перед закрытием отчётного периода.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Не подтверждать несуществующую поставку; проводить приёмку по фактическому исполнению и условиям контракта, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Подписать акт на отсутствующий товар ради закрытия года, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Не подтверждать несуществующую поставку; проводить приёмку по фактическому исполнению и условиям контракта. Основание: Федеральный закон № 44-ФЗ, исполнение и приёмка контракта; БК РФ, исполнение расходов. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Не подтверждать несуществующую поставку; проводить приёмку по фактическому исполнению и условиям контракта. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, исполнение и приёмка контракта; БК РФ, исполнение расходов. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, исполнение и приёмка контракта; БК РФ, исполнение расходов. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, исполнение и приёмка контракта; БК РФ, исполнение расходов. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 44-ФЗ, исполнение и приёмка контракта; БК РФ, исполнение расходов. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Подписать акт на отсутствующий товар ради закрытия года. Надлежащий шаг: Не подтверждать несуществующую поставку; проводить приёмку по фактическому исполнению и условиям контракта. Основание: Федеральный закон № 44-ФЗ, исполнение и приёмка контракта; БК РФ, исполнение расходов. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Подписать акт на отсутствующий товар ради закрытия года. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 44-ФЗ, исполнение и приёмка контракта; БК РФ, исполнение расходов. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"}]},"comic_scene":{"scene_id":"scene-155","title":"Приёмка того, чего нет","case_key":"bank-legal-2026-105","format":"animated-svg","version":4,"alt":"Приёмка того, чего нет: участники изучают поставка и приёмка и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Приёмка того, чего нет»: Поставщик просит подписать акт до поставки, чтобы закрыть год. На складе нет товара; он обещает доставить его после праздников."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 44-ФЗ, исполнение и приёмка контракта; БК РФ, исполнение расходов.. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-106","title":"Жалоба на закупку после договора","category":"Правовая практика","situation":"Участник оспаривает действия заказчика, но срок административного обжалования истёк и контракт заключён. Он просит комиссию отменить договор обычным письмом.\n\nЖалоба поступила после установленного срока административного рассмотрения, а поставщик уже приступил к исполнению контракта. Заявитель приложил переписку и просит вернуть процедуру на этап подачи заявок. Комиссия подготовила черновик письма об отмене договора. Участник получает даты, контракт и жалобу; необходимо определить доступный способ защиты и полномочия органа.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Разграничить административную жалобу и судебную защиту; не отменять заключённый договор вне компетенции и установленной процедуры, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Отменить уже заключённый договор обычным письмом комиссии, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разграничить административную жалобу и судебную защиту; не отменять заключённый договор вне компетенции и установленной процедуры. Основание: Федеральный закон № 44-ФЗ, обжалование закупок; ГК РФ, основания недействительности сделок. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Стратегический критерий: Сохранение права на судебную защиту при пропуске административного срока. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разграничить административную жалобу и судебную защиту; не отменять заключённый договор вне компетенции и установленной процедуры. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":"Сохранение права на судебную защиту при пропуске административного срока.","legal_basis":"Федеральный закон № 44-ФЗ, обжалование закупок; ГК РФ, основания недействительности сделок. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Сохранение права на судебную защиту при пропуске административного срока.","legal_basis":"Федеральный закон № 44-ФЗ, обжалование закупок; ГК РФ, основания недействительности сделок. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Сохранение права на судебную защиту при пропуске административного срока.","legal_basis":"Федеральный закон № 44-ФЗ, обжалование закупок; ГК РФ, основания недействительности сделок. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":"Сохранение права на судебную защиту при пропуске административного срока.","legal_basis":"Федеральный закон № 44-ФЗ, обжалование закупок; ГК РФ, основания недействительности сделок. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Отменить уже заключённый договор обычным письмом комиссии. Надлежащий шаг: Разграничить административную жалобу и судебную защиту; не отменять заключённый договор вне компетенции и установленной процедуры. Основание: Федеральный закон № 44-ФЗ, обжалование закупок; ГК РФ, основания недействительности сделок. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Отменить уже заключённый договор обычным письмом комиссии. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 44-ФЗ, обжалование закупок; ГК РФ, основания недействительности сделок. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-156","title":"Жалоба на закупку после договора","case_key":"bank-legal-2026-106","format":"animated-svg","version":4,"alt":"Жалоба на закупку после договора: участники изучают правовой режим земли и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Жалоба на закупку после договора»: Участник оспаривает действия заказчика, но срок административного обжалования истёк и контракт заключён. Он просит комиссию отменить договор обычным письмом."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 44-ФЗ, обжалование закупок; ГК РФ, основания недействительности сделок.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-107","title":"Подпись под чужим полномочием","category":"Правовая практика","situation":"Сотрудник администрации подписал договор от имени муниципалитета, хотя доверенности и полномочий по должности у него нет. Контрагент уже начал исполнение.\n\nПо положению договоры подписывает глава администрации или лицо с выданной доверенностью. Специалист подписал документ во время отпуска руководителя, не получив замещения или доверенности. Подрядчик уже выполнил подготовительные работы и направил счёт. Участнику нужно оценить возникшие последствия и оформить дальнейшие действия, не скрывая обстоятельства подписания.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Проверить полномочия и последствия сделки без полномочия; последующее одобрение оформляет надлежащее уполномоченное лицо, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Считать договор без полномочия автоматически обязательным для муниципалитета, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить полномочия и последствия сделки без полномочия; последующее одобрение оформляет надлежащее уполномоченное лицо. Основание: ГК РФ, статьи 182–183. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить полномочия и последствия сделки без полномочия; последующее одобрение оформляет надлежащее уполномоченное лицо. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 182–183. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 182–183. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 182–183. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 182–183. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Считать договор без полномочия автоматически обязательным для муниципалитета. Надлежащий шаг: Проверить полномочия и последствия сделки без полномочия; последующее одобрение оформляет надлежащее уполномоченное лицо. Основание: ГК РФ, статьи 182–183. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Считать договор без полномочия автоматически обязательным для муниципалитета. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"ГК РФ, статьи 182–183. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-157","title":"Подпись под чужим полномочием","case_key":"bank-legal-2026-107","format":"animated-svg","version":4,"alt":"Подпись под чужим полномочием: участники изучают обязательства сторон и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Подпись под чужим полномочием»: Сотрудник администрации подписал договор от имени муниципалитета, хотя доверенности и полномочий по должности у него нет. Контрагент уже начал исполнение."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ГК РФ, статьи 182–183.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-108","title":"Молчание как новая аренда","category":"Правовая практика","situation":"Арендатор государственного помещения продолжает пользоваться им после окончания договора. Арендодатель не возражает, но управляющий объявляет это автоматической продажей помещения.\n\nПосле окончания срока аренды организация продолжает платить ту же арендную плату. Собственник получает деньги и не направлял возражений против использования помещения. Управляющий предлагает выдать арендатору свидетельство о собственности вместо нового договора. Участнику доступны прежний договор, платежи и переписка; требуется определить действительное содержание отношений.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","глава","руководитель"],"decision_options":["Разграничить продолжение аренды и переход собственности; пользование не превращает договор в продажу, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Объявить продолжение аренды автоматической продажей помещения, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разграничить продолжение аренды и переход собственности; пользование не превращает договор в продажу. Основание: ГК РФ, статья 621; правила распоряжения публичным имуществом. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разграничить продолжение аренды и переход собственности; пользование не превращает договор в продажу. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ГК РФ, статья 621; правила распоряжения публичным имуществом. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статья 621; правила распоряжения публичным имуществом. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статья 621; правила распоряжения публичным имуществом. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статья 621; правила распоряжения публичным имуществом. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Объявить продолжение аренды автоматической продажей помещения. Надлежащий шаг: Разграничить продолжение аренды и переход собственности; пользование не превращает договор в продажу. Основание: ГК РФ, статья 621; правила распоряжения публичным имуществом. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, глава, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Объявить продолжение аренды автоматической продажей помещения. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","глава","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"ГК РФ, статья 621; правила распоряжения публичным имуществом. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-158","title":"Молчание как новая аренда","case_key":"bank-legal-2026-108","format":"animated-svg","version":4,"alt":"Молчание как новая аренда: участники изучают основание решения и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Молчание как новая аренда»: Арендатор государственного помещения продолжает пользоваться им после окончания договора. Арендодатель не возражает, но управляющий объявляет это автоматической продажей помещения."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ГК РФ, статья 621; правила распоряжения публичным имуществом.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-109","title":"Неустойка за каждый день","category":"Правовая практика","situation":"Подрядчик нарушил срок на десять дней. Договор предусматривает ежедневную пеню, но заказчик одновременно считает её и после фактического исполнения за тот же период.\n\nПоставка должна была завершиться 5 июня, фактически завершилась 15 июня. Заказчик рассчитывает ежедневную пеню до 25 июня, хотя акт исполнения подписан 15 июня без спора о дате. Подрядчик согласен обсуждать десять дней просрочки и просит расчёт по дням. Участнику необходимо проверить период начисления и содержание требования.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["министр труда","министр юстиции","руководитель"],"decision_options":["Определить период нарушения и договорный расчёт; прекратить начисление за устраненное нарушение и оценить основания снижения судом, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Начислять пеню за устранённое нарушение после исполнения, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Определить период нарушения и договорный расчёт; прекратить начисление за устраненное нарушение и оценить основания снижения судом. Основание: ГК РФ, статьи 330 и 333; условия договора. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Определить период нарушения и договорный расчёт; прекратить начисление за устраненное нарушение и оценить основания снижения судом. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 330 и 333; условия договора. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 330 и 333; условия договора. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 330 и 333; условия договора. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ГК РФ, статьи 330 и 333; условия договора. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Начислять пеню за устранённое нарушение после исполнения. Надлежащий шаг: Определить период нарушения и договорный расчёт; прекратить начисление за устраненное нарушение и оценить основания снижения судом. Основание: ГК РФ, статьи 330 и 333; условия договора. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Начислять пеню за устранённое нарушение после исполнения. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"ГК РФ, статьи 330 и 333; условия договора. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-159","title":"Неустойка за каждый день","case_key":"bank-legal-2026-109","format":"animated-svg","version":4,"alt":"Неустойка за каждый день: участники изучают срок и условие и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Неустойка за каждый день»: Подрядчик нарушил срок на десять дней. Договор предусматривает ежедневную пеню, но заказчик одновременно считает её и после фактического исполнения за тот же период."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ГК РФ, статьи 330 и 333; условия договора.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-110","title":"Отказ от гарантийного ремонта","category":"Правовая практика","situation":"Покупатель обнаружил производственный дефект товара в гарантийный период. Продавец требует оплатить экспертизу заранее и отказывается принимать претензию без заводской коробки.\n\nПокупатель принёс неисправный ноутбук через четыре месяца после покупки с чеком и гарантийными документами. Следов неправильного использования продавец пока не установил. Приёмщик требует 4 тыс. ₽ за экспертизу и оригинальную упаковку, которой у покупателя нет. Участник рассматривает претензию до отказа в её регистрации.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["министр труда","министр юстиции","руководитель"],"decision_options":["Принять требование и провести предусмотренную проверку; отсутствие упаковки само по себе не лишает права на защиту, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Отказать в гарантийной претензии из-за отсутствия коробки, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Принять требование и провести предусмотренную проверку; отсутствие упаковки само по себе не лишает права на защиту. Основание: Закон РФ № 2300-1 «О защите прав потребителей», статья 18. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Принять требование и провести предусмотренную проверку; отсутствие упаковки само по себе не лишает права на защиту. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Закон РФ № 2300-1 «О защите прав потребителей», статья 18. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон РФ № 2300-1 «О защите прав потребителей», статья 18. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон РФ № 2300-1 «О защите прав потребителей», статья 18. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон РФ № 2300-1 «О защите прав потребителей», статья 18. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Отказать в гарантийной претензии из-за отсутствия коробки. Надлежащий шаг: Принять требование и провести предусмотренную проверку; отсутствие упаковки само по себе не лишает права на защиту. Основание: Закон РФ № 2300-1 «О защите прав потребителей», статья 18. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Отказать в гарантийной претензии из-за отсутствия коробки. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Закон РФ № 2300-1 «О защите прав потребителей», статья 18. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-160","title":"Отказ от гарантийного ремонта","case_key":"bank-legal-2026-110","format":"animated-svg","version":4,"alt":"Отказ от гарантийного ремонта: участники изучают целевой объект и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Отказ от гарантийного ремонта»: Покупатель обнаружил производственный дефект товара в гарантийный период. Продавец требует оплатить экспертизу заранее и отказывается принимать претензию без заводской коробки."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Закон РФ № 2300-1 «О защите прав потребителей», статья 18.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-111","title":"Цифровая подписка после отказа","category":"Правовая практика","situation":"Потребитель прекратил онлайн-подписку, но сервис продолжает списывать деньги за новые периоды. В интерфейсе кнопка отказа существует, однако заявление не учитывается.\n\nПользователь отменил автопродление 12 мая и получил подтверждение на электронную почту. В июне и июле сервис списал ещё по 900 ₽ и показал активную подписку в кабинете. Поддержка ссылается на отсутствие бумажного заявления, хотя отказ оформлен предусмотренной кнопкой. Участнику переданы условия сервиса, подтверждение и выписка; нужно оценить требование о возврате.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр труда","министр юстиции","руководитель"],"decision_options":["Учитывать надлежащий отказ от договора и проверять правовое основание дальнейших списаний; фактически понесённые расходы должны быть обоснованы, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Продолжить списания новых периодов после надлежащего отказа от подписки, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Учитывать надлежащий отказ от договора и проверять правовое основание дальнейших списаний; фактически понесённые расходы должны быть обоснованы. Основание: Закон РФ № 2300-1, статья 32; ГК РФ, возмездное оказание услуг. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Учитывать надлежащий отказ от договора и проверять правовое основание дальнейших списаний; фактически понесённые расходы должны быть обоснованы. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Закон РФ № 2300-1, статья 32; ГК РФ, возмездное оказание услуг. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон РФ № 2300-1, статья 32; ГК РФ, возмездное оказание услуг. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон РФ № 2300-1, статья 32; ГК РФ, возмездное оказание услуг. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон РФ № 2300-1, статья 32; ГК РФ, возмездное оказание услуг. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Продолжить списания новых периодов после надлежащего отказа от подписки. Надлежащий шаг: Учитывать надлежащий отказ от договора и проверять правовое основание дальнейших списаний; фактически понесённые расходы должны быть обоснованы. Основание: Закон РФ № 2300-1, статья 32; ГК РФ, возмездное оказание услуг. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Продолжить списания новых периодов после надлежащего отказа от подписки. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"Закон РФ № 2300-1, статья 32; ГК РФ, возмездное оказание услуг. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-161","title":"Цифровая подписка после отказа","case_key":"bank-legal-2026-111","format":"animated-svg","version":4,"alt":"Цифровая подписка после отказа: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Цифровая подписка после отказа»: Потребитель прекратил онлайн-подписку, но сервис продолжает списывать деньги за новые периоды. В интерфейсе кнопка отказа существует, однако заявление не учитывается."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Закон РФ № 2300-1, статья 32; ГК РФ, возмездное оказание услуг.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-112","title":"Больничный и увольнение","category":"Правовая практика","situation":"Работодатель издал приказ об увольнении по своей инициативе в день временной нетрудоспособности сотрудника. Ликвидации организации нет.\n\nСотрудник находится на подтверждённом больничном, электронный листок доступен работодателю. Приказ мотивирован сокращением, а организация продолжает деятельность. В кадровом журнале предложена дата увольнения внутри периода нетрудоспособности. Участник должен проверить дату и основание перед выдачей документов и окончательным расчётом.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["министр труда","министр юстиции","руководитель"],"decision_options":["Не проводить увольнение по инициативе работодателя во время нетрудоспособности при отсутствии установленного исключения, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Уволить по инициативе работодателя во время больничного без исключения, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Не проводить увольнение по инициативе работодателя во время нетрудоспособности при отсутствии установленного исключения. Основание: ТК РФ, статья 81. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Не проводить увольнение по инициативе работодателя во время нетрудоспособности при отсутствии установленного исключения. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ТК РФ, статья 81. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статья 81. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статья 81. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статья 81. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Уволить по инициативе работодателя во время больничного без исключения. Надлежащий шаг: Не проводить увольнение по инициативе работодателя во время нетрудоспособности при отсутствии установленного исключения. Основание: ТК РФ, статья 81. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Уволить по инициативе работодателя во время больничного без исключения. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"ТК РФ, статья 81. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-162","title":"Больничный и увольнение","case_key":"bank-legal-2026-112","format":"animated-svg","version":4,"alt":"Больничный и увольнение: участники изучают срок и условие и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Больничный и увольнение»: Работодатель издал приказ об увольнении по своей инициативе в день временной нетрудоспособности сотрудника. Ликвидации организации нет."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ТК РФ, статья 81.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-113","title":"Испытание для беременной","category":"Правовая практика","situation":"При приёме беременной сотрудницы включили в договор испытательный срок. После отрицательного результата начальник собирается прекратить договор как не прошедшей испытание.\n\nСотрудница сообщила о беременности и представила медицинский документ до приёма на работу. В типовой договор автоматически включили трёхмесячное испытание. Через месяц руководитель составил отрицательную оценку и подготовил уведомление о прекращении договора. Участнику переданы договор, документ и оценка; необходимо решить вопрос до вручения уведомления.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр труда","министр юстиции","руководитель"],"decision_options":["Применить запрет испытания для беременной и гарантии прекращения договора; условие об испытании не создаёт права такого увольнения, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Признать беременную не прошедшей запрещённое для неё испытание, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Применить запрет испытания для беременной и гарантии прекращения договора; условие об испытании не создаёт права такого увольнения. Основание: ТК РФ, статьи 70 и 261. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Применить запрет испытания для беременной и гарантии прекращения договора; условие об испытании не создаёт права такого увольнения. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 70 и 261. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 70 и 261. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 70 и 261. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 70 и 261. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Признать беременную не прошедшей запрещённое для неё испытание. Надлежащий шаг: Применить запрет испытания для беременной и гарантии прекращения договора; условие об испытании не создаёт права такого увольнения. Основание: ТК РФ, статьи 70 и 261. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Признать беременную не прошедшей запрещённое для неё испытание. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"ТК РФ, статьи 70 и 261. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-163","title":"Испытание для беременной","case_key":"bank-legal-2026-113","format":"animated-svg","version":4,"alt":"Испытание для беременной: участники изучают срок и условие и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Испытание для беременной»: При приёме беременной сотрудницы включили в договор испытательный срок. После отрицательного результата начальник собирается прекратить договор как не прошедшей испытание."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ТК РФ, статьи 70 и 261.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-114","title":"Отпуск вместо задолженности","category":"Правовая практика","situation":"Работнику не выплатили зарплату два месяца. Бухгалтерия предлагает зачесть задолженность ежегодным отпуском без отпускных и без согласования.\n\nЗадолженность составляет 86 тыс. ₽, даты начислений подтверждены расчётными листками. Работник не просил отпуск и намерен продолжать работу. Бухгалтер предлагает подписать задним числом заявление и считать долг погашенным днями отдыха. Участник должен оценить предложенное оформление и выбрать действие по существующей задолженности.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["министр труда","министр юстиции","руководитель"],"decision_options":["Погасить задолженность и компенсацию; отпуск не заменяет обязанность выплаты заработной платы, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Заменить задолженность по зарплате неоплаченным отпуском, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Погасить задолженность и компенсацию; отпуск не заменяет обязанность выплаты заработной платы. Основание: ТК РФ, статьи 136, 142 и 236. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Погасить задолженность и компенсацию; отпуск не заменяет обязанность выплаты заработной платы. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 136, 142 и 236. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 136, 142 и 236. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 136, 142 и 236. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 136, 142 и 236. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Заменить задолженность по зарплате неоплаченным отпуском. Надлежащий шаг: Погасить задолженность и компенсацию; отпуск не заменяет обязанность выплаты заработной платы. Основание: ТК РФ, статьи 136, 142 и 236. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Заменить задолженность по зарплате неоплаченным отпуском. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"ТК РФ, статьи 136, 142 и 236. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-164","title":"Отпуск вместо задолженности","case_key":"bank-legal-2026-114","format":"animated-svg","version":4,"alt":"Отпуск вместо задолженности: участники изучают срок и условие и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Отпуск вместо задолженности»: Работнику не выплатили зарплату два месяца. Бухгалтерия предлагает зачесть задолженность ежегодным отпуском без отпускных и без согласования."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ТК РФ, статьи 136, 142 и 236.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-115","title":"Обязательная сверхурочная смена","category":"Правовая практика","situation":"Руководитель назначил сверхурочную работу родителю ребёнка до трёх лет без письменного согласия и без ознакомления с правом отказаться. Исключительной ситуации нет.\n\nПроизводственный заказ можно выполнить в течение следующей недели, угрозы аварии или чрезвычайного обстоятельства нет. Работнику с двухлетним ребёнком назначили дополнительную смену сообщением в рабочем чате. Письменное согласие и уведомление о праве отказаться отсутствуют. Участник получает график и сообщение; нужно решить, как оформить работу до начала смены.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр труда","министр юстиции","руководитель"],"decision_options":["Проверить допустимость сверхурочной работы, получить необходимые согласия и уведомить о праве отказа, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Назначить сверхурочную работу без необходимых согласий и уведомления, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить допустимость сверхурочной работы, получить необходимые согласия и уведомить о праве отказа. Основание: ТК РФ, статьи 99 и 259. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить допустимость сверхурочной работы, получить необходимые согласия и уведомить о праве отказа. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 99 и 259. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 99 и 259. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 99 и 259. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"ТК РФ, статьи 99 и 259. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Назначить сверхурочную работу без необходимых согласий и уведомления. Надлежащий шаг: Проверить допустимость сверхурочной работы, получить необходимые согласия и уведомить о праве отказа. Основание: ТК РФ, статьи 99 и 259. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр труда, министр юстиции, руководитель. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Назначить сверхурочную работу без необходимых согласий и уведомления. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр труда","министр юстиции","руководитель"],"lawful":false,"protects_role_interest":false,"legal_basis":"ТК РФ, статьи 99 и 259. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-165","title":"Обязательная сверхурочная смена","case_key":"bank-legal-2026-115","format":"animated-svg","version":4,"alt":"Обязательная сверхурочная смена: участники изучают целевой объект и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Обязательная сверхурочная смена»: Руководитель назначил сверхурочную работу родителю ребёнка до трёх лет без письменного согласия и без ознакомления с правом отказаться. Исключительной ситуации нет."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. ТК РФ, статьи 99 и 259.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-116","title":"Публичный список диагнозов","category":"Правовая практика","situation":"Учреждение вывесило в открытом коридоре имена пациентов с диагнозами, объясняя это удобством приёма. Согласий на такое раскрытие нет.\n\nНа доске у регистратуры указаны фамилии, время приёма и диагнозы двадцати пациентов. Коридор открыт для сопровождающих и посетителей других отделений. Один пациент просит убрать сведения, администратор ссылается на удобство очереди. Участник должен оценить объём раскрытия и организовать запись пациентов с учётом обращения.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","руководитель","глава"],"decision_options":["Удалить публичное раскрытие и организовать приём без разглашения медицинских сведений; обеспечить законное основание обработки, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Оставить имена и диагнозы пациентов на публичном стенде, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Удалить публичное раскрытие и организовать приём без разглашения медицинских сведений; обеспечить законное основание обработки. Основание: Федеральные законы № 152-ФЗ и № 323-ФЗ, врачебная тайна и специальные категории данных. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Удалить публичное раскрытие и организовать приём без разглашения медицинских сведений; обеспечить законное основание обработки. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральные законы № 152-ФЗ и № 323-ФЗ, врачебная тайна и специальные категории данных. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральные законы № 152-ФЗ и № 323-ФЗ, врачебная тайна и специальные категории данных. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральные законы № 152-ФЗ и № 323-ФЗ, врачебная тайна и специальные категории данных. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральные законы № 152-ФЗ и № 323-ФЗ, врачебная тайна и специальные категории данных. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Оставить имена и диагнозы пациентов на публичном стенде. Надлежащий шаг: Удалить публичное раскрытие и организовать приём без разглашения медицинских сведений; обеспечить законное основание обработки. Основание: Федеральные законы № 152-ФЗ и № 323-ФЗ, врачебная тайна и специальные категории данных. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Оставить имена и диагнозы пациентов на публичном стенде. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральные законы № 152-ФЗ и № 323-ФЗ, врачебная тайна и специальные категории данных. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-166","title":"Публичный список диагнозов","case_key":"bank-legal-2026-116","format":"animated-svg","version":4,"alt":"Публичный список диагнозов: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Публичный список диагнозов»: Учреждение вывесило в открытом коридоре имена пациентов с диагнозами, объясняя это удобством приёма. Согласий на такое раскрытие нет."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральные законы № 152-ФЗ и № 323-ФЗ, врачебная тайна и специальные категории данных.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-117","title":"Паспорт на личную почту","category":"Правовая практика","situation":"Служащий отправил сканы паспортов заявителей на свою личную почту для работы дома. Разрешённого защищённого канала и установленного основания такой передачи нет.\n\nДля подготовки отчёта служащий скачал сканы двенадцати паспортов из ведомственной системы. Личный почтовый сервис хранит вложения за пределами разрешённого рабочего контура. Руководитель узнал о передаче до публикации отчёта, доступ к письму пока не ограничен. Участнику доступны журнал выгрузки и служебное объяснение; нужно выбрать действия по инциденту.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","руководитель","глава"],"decision_options":["Прекратить неподконтрольную передачу, оценить инцидент и использовать предусмотренный защищённый порядок обработки, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Разрешить пересылку паспортов на личную почту без защищённого порядка, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Прекратить неподконтрольную передачу, оценить инцидент и использовать предусмотренный защищённый порядок обработки. Основание: Федеральный закон № 152-ФЗ, обязанности оператора и безопасность персональных данных. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Прекратить неподконтрольную передачу, оценить инцидент и использовать предусмотренный защищённый порядок обработки. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 152-ФЗ, обязанности оператора и безопасность персональных данных. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 152-ФЗ, обязанности оператора и безопасность персональных данных. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 152-ФЗ, обязанности оператора и безопасность персональных данных. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 152-ФЗ, обязанности оператора и безопасность персональных данных. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Разрешить пересылку паспортов на личную почту без защищённого порядка. Надлежащий шаг: Прекратить неподконтрольную передачу, оценить инцидент и использовать предусмотренный защищённый порядок обработки. Основание: Федеральный закон № 152-ФЗ, обязанности оператора и безопасность персональных данных. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Разрешить пересылку паспортов на личную почту без защищённого порядка. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 152-ФЗ, обязанности оператора и безопасность персональных данных. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-167","title":"Паспорт на личную почту","case_key":"bank-legal-2026-117","format":"animated-svg","version":4,"alt":"Паспорт на личную почту: участники изучают проверка данных и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Паспорт на личную почту»: Служащий отправил сканы паспортов заявителей на свою личную почту для работы дома. Разрешённого защищённого канала и установленного основания такой передачи нет."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 152-ФЗ, обязанности оператора и безопасность персональных данных.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-118","title":"Камера с распознаванием лиц","category":"Правовая практика","situation":"Муниципальное учреждение вводит идентификацию посетителей по лицу. Оно считает, что таблички «ведётся видеонаблюдение» достаточно для любых биометрических процедур.\n\nТурникет сопоставляет изображение лица посетителя с заранее созданным профилем и сохраняет результат идентификации. Альтернативный способ входа не предусмотрен, а посетители увидели только общую табличку о видеонаблюдении. Учреждение ещё не утвердило отдельный порядок обработки этих данных. Участник оценивает запуск системы до её обязательного использования.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","руководитель","глава"],"decision_options":["Разделить обычное видеонаблюдение и биометрическую идентификацию; установить законное основание, требования и допустимые альтернативы, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Считать табличку о камере достаточным основанием для любой биометрии, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разделить обычное видеонаблюдение и биометрическую идентификацию; установить законное основание, требования и допустимые альтернативы. Основание: Федеральный закон № 152-ФЗ, статья 11; законодательство о биометрической идентификации. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разделить обычное видеонаблюдение и биометрическую идентификацию; установить законное основание, требования и допустимые альтернативы. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 152-ФЗ, статья 11; законодательство о биометрической идентификации. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 152-ФЗ, статья 11; законодательство о биометрической идентификации. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 152-ФЗ, статья 11; законодательство о биометрической идентификации. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 152-ФЗ, статья 11; законодательство о биометрической идентификации. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Считать табличку о камере достаточным основанием для любой биометрии. Надлежащий шаг: Разделить обычное видеонаблюдение и биометрическую идентификацию; установить законное основание, требования и допустимые альтернативы. Основание: Федеральный закон № 152-ФЗ, статья 11; законодательство о биометрической идентификации. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Считать табличку о камере достаточным основанием для любой биометрии. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 152-ФЗ, статья 11; законодательство о биометрической идентификации. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-168","title":"Камера с распознаванием лиц","case_key":"bank-legal-2026-118","format":"animated-svg","version":4,"alt":"Камера с распознаванием лиц: участники изучают целевой объект и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Камера с распознаванием лиц»: Муниципальное учреждение вводит идентификацию посетителей по лицу. Оно считает, что таблички «ведётся видеонаблюдение» достаточно для любых биометрических процедур."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 152-ФЗ, статья 11; законодательство о биометрической идентификации.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-119","title":"Ответ на обращение без сути","category":"Правовая практика","situation":"Житель указал конкретную неисправность и просит информацию о сроке ремонта. Орган прислал общую рекламу своей работы, не рассмотрев поставленный вопрос.\n\nВ обращении указаны адрес аварийного участка, даты предыдущих заявок и просьба сообщить план ремонта. Ответ содержит фотографии благоустройства другого квартала и общую благодарность за активность. Срок ответа подошёл к концу, заявитель уточняет, рассмотрены ли его вопросы. Участнику переданы оба текста; нужно определить содержание дальнейшего ответа.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","руководитель","глава"],"decision_options":["Рассмотреть доводы в пределах компетенции и дать ответ по существу либо направить обращение надлежащему органу с уведомлением, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Ответить на конкретное обращение общей рекламой ведомства, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Рассмотреть доводы в пределах компетенции и дать ответ по существу либо направить обращение надлежащему органу с уведомлением. Основание: Федеральный закон № 59-ФЗ, рассмотрение обращения по существу. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Рассмотреть доводы в пределах компетенции и дать ответ по существу либо направить обращение надлежащему органу с уведомлением. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Федеральный закон № 59-ФЗ, рассмотрение обращения по существу. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 59-ФЗ, рассмотрение обращения по существу. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 59-ФЗ, рассмотрение обращения по существу. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Федеральный закон № 59-ФЗ, рассмотрение обращения по существу. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Ответить на конкретное обращение общей рекламой ведомства. Надлежащий шаг: Рассмотреть доводы в пределах компетенции и дать ответ по существу либо направить обращение надлежащему органу с уведомлением. Основание: Федеральный закон № 59-ФЗ, рассмотрение обращения по существу. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Ответить на конкретное обращение общей рекламой ведомства. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 59-ФЗ, рассмотрение обращения по существу. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-169","title":"Ответ на обращение без сути","case_key":"bank-legal-2026-119","format":"animated-svg","version":4,"alt":"Ответ на обращение без сути: участники изучают поставка и приёмка и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Ответ на обращение без сути»: Житель указал конкретную неисправность и просит информацию о сроке ремонта. Орган прислал общую рекламу своей работы, не рассмотрев поставленный вопрос."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 59-ФЗ, рассмотрение обращения по существу.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-120","title":"Тайна вместо открытого бюджета","category":"Правовая практика","situation":"Орган отказывает в доступе к опубликованным бюджетным данным, объявив весь свой бюджет служебной тайной. Ограничение законом не обосновано.\n\nЗапрошены утверждённые доходы, расходы и пояснения к опубликованному бюджету. Эти материалы уже размещались на сайте совета, но после обновления раздела ссылки перестали открываться. В отказе отсутствует ссылка на конкретное ограничение доступа. Участник должен решить, как обработать запрос и восстановить доступ к соответствующим материалам.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","руководитель","глава"],"decision_options":["Разграничить открытые сведения и законно ограниченную информацию; предоставить доступ к открытым бюджетным данным, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Объявить все бюджетные сведения служебной тайной без законного основания, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разграничить открытые сведения и законно ограниченную информацию; предоставить доступ к открытым бюджетным данным. Основание: Федеральный закон № 8-ФЗ; БК РФ, принцип прозрачности. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Стратегический критерий: Защита доверия к органу власти через законную бюджетную открытость. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разграничить открытые сведения и законно ограниченную информацию; предоставить доступ к открытым бюджетным данным. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":"Защита доверия к органу власти через законную бюджетную открытость.","legal_basis":"Федеральный закон № 8-ФЗ; БК РФ, принцип прозрачности. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита доверия к органу власти через законную бюджетную открытость.","legal_basis":"Федеральный закон № 8-ФЗ; БК РФ, принцип прозрачности. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита доверия к органу власти через законную бюджетную открытость.","legal_basis":"Федеральный закон № 8-ФЗ; БК РФ, принцип прозрачности. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":"Защита доверия к органу власти через законную бюджетную открытость.","legal_basis":"Федеральный закон № 8-ФЗ; БК РФ, принцип прозрачности. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Объявить все бюджетные сведения служебной тайной без законного основания. Надлежащий шаг: Разграничить открытые сведения и законно ограниченную информацию; предоставить доступ к открытым бюджетным данным. Основание: Федеральный закон № 8-ФЗ; БК РФ, принцип прозрачности. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Объявить все бюджетные сведения служебной тайной без законного основания. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"Федеральный закон № 8-ФЗ; БК РФ, принцип прозрачности. Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721"}]},"comic_scene":{"scene_id":"scene-170","title":"Тайна вместо открытого бюджета","case_key":"bank-legal-2026-120","format":"animated-svg","version":4,"alt":"Тайна вместо открытого бюджета: участники изучают бюджетное основание и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Тайна вместо открытого бюджета»: Орган отказывает в доступе к опубликованным бюджетным данным, объявив весь свой бюджет служебной тайной. Ограничение законом не обосновано."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Федеральный закон № 8-ФЗ; БК РФ, принцип прозрачности.. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-121","title":"Согласование мирного собрания","category":"Правовая практика","situation":"Орган получил уведомление о публичном мероприятии и вместо предусмотренной процедуры потребовал разрешение партийного руководства. Законного основания такого документа нет.\n\nОрганизаторы подали уведомление в установленный срок с маршрутом и предполагаемым числом участников. Администрация не направила мотивированного предложения по месту, а запросила согласие местного партийного руководителя. Срок ответа на уведомление истекает завтра. Участнику доступны уведомление и проект требования; необходимо выбрать дальнейшее действие органа.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","руководитель","глава"],"decision_options":["Рассмотреть уведомление в установленном законом порядке; партийное разрешение не относится к требуемым документам, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Потребовать партийное разрешение для мирного собрания, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Рассмотреть уведомление в установленном законом порядке; партийное разрешение не относится к требуемым документам. Основание: Конституция РФ, статья 31; Федеральный закон № 54-ФЗ. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Рассмотреть уведомление в установленном законом порядке; партийное разрешение не относится к требуемым документам. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 31; Федеральный закон № 54-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 31; Федеральный закон № 54-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 31; Федеральный закон № 54-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 31; Федеральный закон № 54-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Потребовать партийное разрешение для мирного собрания. Надлежащий шаг: Рассмотреть уведомление в установленном законом порядке; партийное разрешение не относится к требуемым документам. Основание: Конституция РФ, статья 31; Федеральный закон № 54-ФЗ. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Потребовать партийное разрешение для мирного собрания. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статья 31; Федеральный закон № 54-ФЗ. Источник: http://www.kremlin.ru/acts/constitution"}]},"comic_scene":{"scene_id":"scene-171","title":"Согласование мирного собрания","case_key":"bank-legal-2026-121","format":"animated-svg","version":4,"alt":"Согласование мирного собрания: участники изучают выбор и протокол и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Согласование мирного собрания»: Орган получил уведомление о публичном мероприятии и вместо предусмотренной процедуры потребовал разрешение партийного руководства. Законного основания такого документа нет."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статья 31; Федеральный закон № 54-ФЗ.. http://www.kremlin.ru/acts/constitution Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-122","title":"Отсутствие состава нарушения","category":"Правовая практика","situation":"Контрольный орган доказал факт хозяйственной деятельности, но не установил обязательный признак административного состава. Он предлагает назначить штраф для профилактики.\n\nВ материалах есть фотографии и договор, подтверждающие работу предприятия. Для вменённого состава необходимо дополнительное обстоятельство, которого проверка не установила. Инспектор предлагает компенсировать этот пробел ссылкой на общественную опасность деятельности. Участник оценивает доказательства перед вынесением постановления.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","руководитель","глава"],"decision_options":["Проверить все признаки состава; при их отсутствии прекратить производство по надлежащему основанию, а не штрафовать для примера, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Назначить профилактический штраф без состава нарушения, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить все признаки состава; при их отсутствии прекратить производство по надлежащему основанию, а не штрафовать для примера. Основание: КоАП РФ, статьи 1.5 и 24.5. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить все признаки состава; при их отсутствии прекратить производство по надлежащему основанию, а не штрафовать для примера. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"КоАП РФ, статьи 1.5 и 24.5. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, статьи 1.5 и 24.5. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, статьи 1.5 и 24.5. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, статьи 1.5 и 24.5. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Назначить профилактический штраф без состава нарушения. Надлежащий шаг: Проверить все признаки состава; при их отсутствии прекратить производство по надлежащему основанию, а не штрафовать для примера. Основание: КоАП РФ, статьи 1.5 и 24.5. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Назначить профилактический штраф без состава нарушения. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"КоАП РФ, статьи 1.5 и 24.5. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-172","title":"Отсутствие состава нарушения","case_key":"bank-legal-2026-122","format":"animated-svg","version":4,"alt":"Отсутствие состава нарушения: участники изучают основание решения и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Отсутствие состава нарушения»: Контрольный орган доказал факт хозяйственной деятельности, но не установил обязательный признак административного состава. Он предлагает назначить штраф для профилактики."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. КоАП РФ, статьи 1.5 и 24.5.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-123","title":"Протокол без извещения","category":"Правовая практика","situation":"Орган составил протокол и рассмотрел дело без надлежащего извещения лица. Доказательств извещения нет, исключительные основания не установлены.\n\nУведомление отправили на старый адрес, хотя новый адрес указан в материалах проверки. Почтовое сообщение вернулось, иных подтверждений извещения нет. Дело рассмотрели в отсутствие лица, после чего ему направили только итоговое постановление. Участнику нужно оценить соблюдение процедуры и дальнейшее движение дела.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["министр юстиции","руководитель","глава"],"decision_options":["Обеспечить извещение и право на защиту; устранить процессуальное нарушение установленным способом, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Рассмотреть дело без доказательств надлежащего извещения, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Обеспечить извещение и право на защиту; устранить процессуальное нарушение установленным способом. Основание: КоАП РФ, процессуальные права лица и порядок рассмотрения дела. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Обеспечить извещение и право на защиту; устранить процессуальное нарушение установленным способом. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"КоАП РФ, процессуальные права лица и порядок рассмотрения дела. Источник: https://pravo.gov.ru/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, процессуальные права лица и порядок рассмотрения дела. Источник: https://pravo.gov.ru/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, процессуальные права лица и порядок рассмотрения дела. Источник: https://pravo.gov.ru/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"КоАП РФ, процессуальные права лица и порядок рассмотрения дела. Источник: https://pravo.gov.ru/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Рассмотреть дело без доказательств надлежащего извещения. Надлежащий шаг: Обеспечить извещение и право на защиту; устранить процессуальное нарушение установленным способом. Основание: КоАП РФ, процессуальные права лица и порядок рассмотрения дела. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр юстиции, руководитель, глава. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Рассмотреть дело без доказательств надлежащего извещения. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр юстиции","руководитель","глава"],"lawful":false,"protects_role_interest":false,"legal_basis":"КоАП РФ, процессуальные права лица и порядок рассмотрения дела. Источник: https://pravo.gov.ru/"}]},"comic_scene":{"scene_id":"scene-173","title":"Протокол без извещения","case_key":"bank-legal-2026-123","format":"animated-svg","version":4,"alt":"Протокол без извещения: участники изучают юридический документ и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Протокол без извещения»: Орган составил протокол и рассмотрел дело без надлежащего извещения лица. Доказательств извещения нет, исключительные основания не установлены."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. КоАП РФ, процессуальные права лица и порядок рассмотрения дела.. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-124","title":"Налог по ведомственной памятке","category":"Правовая практика","situation":"Инспекция требует доплатить налог по ставке из памятки, которая расходится с применимым законом. Налогоплательщик представил расчёт по НК РФ.\n\nВ применимой редакции закона указана ставка 2%, а в памятке на стойке инспекции — 3%. Организация представила налоговый расчёт и копию действующей нормы за соответствующий период. Инспектор требует доплату, ссылаясь на одинаковую памятку во всех отделениях. Участник проверяет нормативное основание перед подготовкой требования.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","налоговой"],"decision_options":["Применить действующую норму налогового законодательства; ведомственная памятка не изменяет ставку, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Применить налоговую ставку из памятки вместо закона, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Применить действующую норму налогового законодательства; ведомственная памятка не изменяет ставку. Основание: Конституция РФ, статья 57; НК РФ, принципы законодательства о налогах. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, налоговой. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Применить действующую норму налогового законодательства; ведомственная памятка не изменяет ставку. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","налоговой"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 57; НК РФ, принципы законодательства о налогах. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","налоговой"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 57; НК РФ, принципы законодательства о налогах. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","налоговой"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 57; НК РФ, принципы законодательства о налогах. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","налоговой"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Конституция РФ, статья 57; НК РФ, принципы законодательства о налогах. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Применить налоговую ставку из памятки вместо закона. Надлежащий шаг: Применить действующую норму налогового законодательства; ведомственная памятка не изменяет ставку. Основание: Конституция РФ, статья 57; НК РФ, принципы законодательства о налогах. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, налоговой. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Применить налоговую ставку из памятки вместо закона. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","налоговой"],"lawful":false,"protects_role_interest":false,"legal_basis":"Конституция РФ, статья 57; НК РФ, принципы законодательства о налогах. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"}]},"comic_scene":{"scene_id":"scene-174","title":"Налог по ведомственной памятке","case_key":"bank-legal-2026-124","format":"animated-svg","version":4,"alt":"Налог по ведомственной памятке: участники изучают бюджетное основание и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Налог по ведомственной памятке»: Инспекция требует доплатить налог по ставке из памятки, которая расходится с применимым законом. Налогоплательщик представил расчёт по НК РФ."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Конституция РФ, статья 57; НК РФ, принципы законодательства о налогах.. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-125","title":"Излишне взысканный налог","category":"Правовая практика","situation":"Со счёта организации взыскали сумму, затем отменённую решением по спору. Бухгалтерия инспекции предлагает засчитать её в неопределённые будущие платежи без установленной процедуры.\n\nПо результатам рассмотрения спора взыскание 480 тыс. ₽ признано необоснованным. Деньги уже списаны со счёта, организация представила решение и реквизиты. В проекте ответа отсутствуют срок, расчёт и указание применимой процедуры; предложено ждать будущей налоговой обязанности. Участнику нужно выбрать действие, учитывающее состояние расчётов и содержание отмены.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","налоговой"],"decision_options":["Установить состояние расчётов и применить предусмотренный НК РФ порядок возврата или зачёта, учитывая отменённое взыскание, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Оставить отменённое взыскание на неопределённые будущие платежи без процедуры, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Установить состояние расчётов и применить предусмотренный НК РФ порядок возврата или зачёта, учитывая отменённое взыскание. Основание: НК РФ, единый налоговый счёт и возврат положительного сальдо; последствия отмены взыскания. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, налоговой. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Установить состояние расчётов и применить предусмотренный НК РФ порядок возврата или зачёта, учитывая отменённое взыскание. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","налоговой"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"НК РФ, единый налоговый счёт и возврат положительного сальдо; последствия отмены взыскания. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","налоговой"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, единый налоговый счёт и возврат положительного сальдо; последствия отмены взыскания. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","налоговой"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, единый налоговый счёт и возврат положительного сальдо; последствия отмены взыскания. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","налоговой"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, единый налоговый счёт и возврат положительного сальдо; последствия отмены взыскания. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Оставить отменённое взыскание на неопределённые будущие платежи без процедуры. Надлежащий шаг: Установить состояние расчётов и применить предусмотренный НК РФ порядок возврата или зачёта, учитывая отменённое взыскание. Основание: НК РФ, единый налоговый счёт и возврат положительного сальдо; последствия отмены взыскания. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, налоговой. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Оставить отменённое взыскание на неопределённые будущие платежи без процедуры. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","налоговой"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, единый налоговый счёт и возврат положительного сальдо; последствия отмены взыскания. Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/"}]},"comic_scene":{"scene_id":"scene-175","title":"Излишне взысканный налог","case_key":"bank-legal-2026-125","format":"animated-svg","version":4,"alt":"Излишне взысканный налог: участники изучают бюджетное основание и документы по ситуации.","media_label":"Правовой курьер","news_lead":"Ситуация «Излишне взысканный налог»: Со счёта организации взыскали сумму, затем отменённую решением по спору. Бухгалтерия инспекции предлагает засчитать её в неопределённые будущие платежи без установленной процедуры."},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, единый налоговый счёт и возврат положительного сальдо; последствия отмены взыскания.. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."}]$authored$::jsonb))
INSERT INTO private.authored_event_catalog(case_key,content)
