UPDATE public.event_cases e SET situation=c.content->>'situation',decision_options=c.content->'decision_options',effect_plan=c.content->'effect_plan',allowed_roles=ARRAY(SELECT jsonb_array_elements_text(c.content->'allowed_roles'))
FROM private.authored_event_catalog c WHERE e.case_key=c.case_key AND e.case_key IN ('bank-legal-2026-101','bank-legal-2026-102','bank-legal-2026-103','bank-legal-2026-104','bank-legal-2026-105','bank-legal-2026-106','bank-legal-2026-107','bank-legal-2026-108','bank-legal-2026-109','bank-legal-2026-110','bank-legal-2026-111','bank-legal-2026-112','bank-legal-2026-113','bank-legal-2026-114','bank-legal-2026-115','bank-legal-2026-116','bank-legal-2026-117','bank-legal-2026-118','bank-legal-2026-119','bank-legal-2026-120','bank-legal-2026-121','bank-legal-2026-122','bank-legal-2026-123','bank-legal-2026-124','bank-legal-2026-125')
AND NOT EXISTS(SELECT 1 FROM public.event_assignments a WHERE a.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_decisions d WHERE d.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_case_outcomes o WHERE o.case_id=e.id);
